// Ported from the Node app's Sequelize model DocumentCheck (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class DocumentCheckConfiguration : IEntityTypeConfiguration<DocumentCheck>
{
    public void Configure(EntityTypeBuilder<DocumentCheck> builder)
    {
        builder.ToTable("document_checks", t =>
        {
            t.HasCheckConstraint("CK_document_checks_status", "[status] IN (N'pending', N'verified', N'rejected')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(160)").HasMaxLength(160).IsRequired();
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'pending'");
        builder.Property(e => e.Note).HasColumnName("note").HasColumnType("nvarchar(300)").HasMaxLength(300);
        builder.Property(e => e.CheckedByName).HasColumnName("checked_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.CheckedOn).HasColumnName("checked_on").HasColumnType("datetime2");
        builder.HasIndex(e => new { e.StudentId, e.Title }).IsUnique().HasDatabaseName("uq_document_check");
        builder.HasOne(e => e.Student).WithMany(p => p.DocumentChecks).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
